import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Banner","description":"","frontmatter":{},"headers":[],"relativePath":"components/banner.md","filePath":"components/banner.md"}'),n={name:"components/banner.md"};function d(i,e,s,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="banner" tabindex="-1">Banner <a class="header-anchor" href="#banner" aria-label="Permalink to &quot;Banner&quot;">​</a></h1><p>Banner is a notice in the flow of a page or a panel.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a notice that stays until its cause is gone: a warning, an error, a state of the document. A remark without a line is a <a href="./note">Note</a>; a short message that goes by itself is a <a href="./toast">Toast</a>. The notices of a whole application go in <a href="./notices">Notices</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tone</code></td><td>required</td><td><code>info</code>, <code>warn</code>, <code>error</code> or <code>ok</code></td></tr><tr><td><code>act</code></td><td></td><td>An action at the right end (a snippet)</td></tr><tr><td><code>floating</code></td><td><code>false</code></td><td>The panel surface, for a notice over the stage</td></tr><tr><td><code>label</code></td><td></td><td>The accessible name, when it is referred to by name</td></tr><tr><td><code>children</code></td><td>required</td><td>The text, or a Stack of several lines</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>Its line and its icon take the color of the tone (blue, yellow, red, green); it has pad-md inside, the icon gap-sm from the text, centred on the first line, which is not trimmed. The action sits at the right end, gap-sm from the text; when it does not fit beside the text it moves below it, and shrinks to the container with an ellipsis. Its role is <code>alert</code> for an error and <code>status</code> otherwise.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/banner/" title="Banner" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/banner/" target="_blank" rel="noopener">Banner</a></figcaption></figure>',10)])])}const m=t(n,[["render",d]]);export{f as __pageData,m as default};
